-- Four further source-attributed adaptations and a cross-sitting occurrence.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q41','exam-fe','セキュリティバイデザイン','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問41・改編】セキュリティバイデザインを説明したものはどれか。','[{"id":"a","text":"完成後のシステムについて第三者が脆弱性診断を実施する"},{"id":"b","text":"完成後にリスク評価の結果に基づいてシステムを改修する"},{"id":"c","text":"運用中に第三者監査の結果に基づいてシステムを改修する"},{"id":"d","text":"企画・設計の段階からセキュリティを確保する"}]','"d"','セキュリティバイデザインは企画・設計の初期から安全性を組み込む方策である。\n\n中文解析：安全设计从系统企划和设计阶段就考虑安全，而不是等系统完成后才处理。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q42','exam-fe','TCPポート80','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問42・改編】侵入済みマルウェアが外部の指令サーバとの通信にTCP宛先ポート80を使う理由として適切なものはどれか。','[{"id":"a","text":"DNSゾーン転送用なのでファイアウォールで許可されやすい"},{"id":"b","text":"HTTPS閲覧用なので侵入検知システムに検知されにくい"},{"id":"c","text":"Web閲覧用なのでファイアウォールで許可されている可能性が高い"},{"id":"d","text":"名前解決用なので侵入検知システムに検知されにくい"}]','"c"','TCP 80はHTTPの標準ポートで、Web閲覧のために通信が許可されている場合がある。HTTPSは通常443、DNSは通常53を使う。\n\n中文解析：TCP 80通常用于HTTP网页访问，可能被防火墙允许；HTTPS通常为443，DNS通常为53。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q46','exam-fe','決定表','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問46・改編】システム開発で用いる決定表の説明として適切なものはどれか。','[{"id":"a","text":"実体を長方形、関係を線で表す"},{"id":"b","text":"外部インタフェース・処理・データストア間のデータの流れを表す"},{"id":"c","text":"条件の組合せと各組合せに対応する動作を表す"},{"id":"d","text":"処理や選択の制御の流れを線や矢印で表す"}]','"c"','決定表は複数条件の組合せごとに実行すべき動作を整理する。実体と関係はER図、データの流れはDFD、制御の流れは流れ図で表す。\n\n中文解析：判定表整理各种条件组合及对应动作；实体关系图、数据流图和流程图分别用于其他表示目的。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q50','exam-fe','リバースエンジニアリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問50・改編】稼働中のデータベースの定義情報から、モデリングツールでER図などの設計書を生成する手法はどれか。','[{"id":"a","text":"コンカレントエンジニアリング"},{"id":"b","text":"ソーシャルエンジニアリング"},{"id":"c","text":"フォワードエンジニアリング"},{"id":"d","text":"リバースエンジニアリング"}]','"d"','既存の実装や定義情報から設計を復元するのはリバースエンジニアリングである。設計から実装を作る方向はフォワードエンジニアリングである。\n\n中文解析：从现有数据库定义还原设计属于逆向工程；从设计生成实现是正向工程。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
